CREATE TABLE IF NOT EXISTS customers (id bigserial primary key, customer_number varchar(20) not null unique, first_name varchar(50) not null, last_name varchar(50) not null, email varchar(100) not null unique, mobile_number varchar(15) not null unique, date_of_birth date not null, nationality varchar(50) not null, status varchar(20) not null, kyc_verified boolean not null default false, created_at timestamp not null, updated_at timestamp not null);
